import {
  isUuidV4,
  isValidCompletedDate,
  isValidGeometry,
  MAX_PUBLISHED_ACTIVITIES,
  publishedFeature,
} from "./domain";
import type { ActiveRun, CompletedActivity, TourDraft, ToursState } from "./types";

const validIsoDateTime = (value: unknown): value is string => {
  if (typeof value !== "string") return false;
  const parsed = new Date(value);
  return !Number.isNaN(parsed.getTime()) && parsed.toISOString() === value;
};

/**
 * Drafts used to carry an activity and could be generated by OSRM. Routes are
 * neutral now: old geometry remains usable, while activity-specific metadata
 * is deliberately removed during hydration.
 */
const normalizeDraft = (draft: unknown): TourDraft | null => {
  const value = draft as Record<string, unknown> | null;
  if (
    !value ||
    !isUuidV4(value.id) ||
    typeof value.name !== "string" ||
    typeof value.routeSource !== "string" ||
    !new Set(["drawn", "osrm", "gpx", "geojson"]).has(value.routeSource) ||
    !isValidGeometry(value.geometry as TourDraft["geometry"]) ||
    !validIsoDateTime(value.createdAt) ||
    !validIsoDateTime(value.updatedAt)
  ) {
    return null;
  }

  const routeSource = value.routeSource === "osrm" ? "drawn" : value.routeSource;
  const normalized: TourDraft = {
    id: value.id,
    name: value.name,
    routeSource: routeSource as TourDraft["routeSource"],
    geometry: value.geometry as TourDraft["geometry"],
    createdAt: value.createdAt,
    updatedAt: value.updatedAt,
  };

  // A GPX elapsed time is route data. Old OSRM/default-speed durations depended
  // on the former draft activity and therefore cannot be kept on a neutral route.
  if (
    routeSource === "gpx" &&
    value.durationSource === "gpx" &&
    typeof value.durationMinutes === "number" &&
    Number.isFinite(value.durationMinutes) &&
    value.durationMinutes > 0
  ) {
    normalized.durationMinutes = value.durationMinutes;
    normalized.durationSource = "gpx";
  }
  return normalized;
};

const normalizeActivity = (activity: unknown): CompletedActivity | null => {
  const value = activity as CompletedActivity;
  if (
    !value ||
    !isUuidV4(value.id) ||
    !isUuidV4(value.draftId) ||
    typeof value.name !== "string" ||
    !isValidCompletedDate(value.completedDate) ||
    !validIsoDateTime(value.completedAt) ||
    !isValidGeometry(value.geometry)
  ) {
    return null;
  }
  try {
    publishedFeature(value, "49f3344a-e58b-4f6a-a874-84e3815620e6");
    return value;
  } catch {
    return null;
  }
};

const validateStateCollections = (input: unknown): ToursState => {
  const state = input as ToursState;
  if (
    !state ||
    state.schemaVersion !== 1 ||
    !Array.isArray(state.drafts) ||
    !Array.isArray(state.activities)
  ) {
    throw new Error("Der Solid-Tours-Status hat ein ungültiges oder unbekanntes Format.");
  }
  const drafts = state.drafts.map(normalizeDraft);
  const activities = state.activities.map(normalizeActivity);
  if (drafts.some((draft) => draft === null) || activities.some((activity) => activity === null)) {
    throw new Error("Der Solid-Tours-Status hat ein ungültiges oder unbekanntes Format.");
  }
  return {
    ...state,
    drafts: drafts as TourDraft[],
    activities: activities as CompletedActivity[],
  };
};

export function validateActiveRun(podRoot: string, activeRun: unknown): ActiveRun {
  const value = activeRun as Record<string, unknown> | null;
  if (!value || !isUuidV4(value.scenarioRunId)) {
    throw new Error("Der aktive Szenariolauf enthält ungültige Kennungen.");
  }
  const phase = value.phase === undefined ? "published" : value.phase;
  if (!new Set(["publishing", "published", "resetting"]).has(String(phase))) {
    throw new Error("Der aktive Szenariolauf enthaelt eine ungueltige Publish-Phase.");
  }
  const legacyActivityId = value.activityId;
  const activityIds = Array.isArray(value.activityIds)
    ? value.activityIds
    : isUuidV4(legacyActivityId)
      ? [legacyActivityId]
      : [];
  if (
    activityIds.length === 0 ||
    activityIds.length > MAX_PUBLISHED_ACTIVITIES ||
    !activityIds.every(isUuidV4) ||
    new Set(activityIds).size !== activityIds.length
  ) {
    throw new Error("Der aktive Szenariolauf enthält ungültige Aktivitätskennungen.");
  }
  const normalizedPodRoot = podRoot.endsWith("/") ? podRoot : `${podRoot}/`;
  const runContainerUrl = `${normalizedPodRoot}solid-tours/runs/${value.scenarioRunId}/`;
  const datasetIdentifier = `solid-tours-activity-${value.scenarioRunId}`;
  const expected = {
    runContainerUrl,
    resourceUrl: `${runContainerUrl}activity.geojson`,
    manifestUrl: `${runContainerUrl}manifest.ttl`,
    datasetIdentifier,
    catalogDatasetUrl: `${normalizedPodRoot}catalog/ds/${datasetIdentifier}.ttl#it`,
  };
  for (const [key, expectedValue] of Object.entries(expected)) {
    if ((value as unknown as Record<string, unknown>)[key] !== expectedValue) {
      throw new Error(`Der aktive Szenariolauf enthält eine unerwartete ${key}-Adresse.`);
    }
  }
  if (!validIsoDateTime(value.publishedAt)) {
    throw new Error("Der aktive Szenariolauf enthält keinen gültigen Publish-Zeitpunkt.");
  }
  return {
    phase: phase as ActiveRun["phase"],
    scenarioRunId: value.scenarioRunId,
    activityIds,
    resourceUrl: expected.resourceUrl,
    manifestUrl: expected.manifestUrl,
    runContainerUrl: expected.runContainerUrl,
    datasetIdentifier: expected.datasetIdentifier,
    catalogDatasetUrl: expected.catalogDatasetUrl,
    publishedAt: value.publishedAt,
  };
}

export function validateToursState(podRoot: string, input: unknown): ToursState {
  const state = validateStateCollections(input);
  if (state.activeRun !== null) {
    const activeRun = validateActiveRun(podRoot, state.activeRun);
    if (!activeRun.activityIds.every((activityId) => state.activities.some((activity) => activity.id === activityId))) {
      throw new Error("Der aktive Szenariolauf verweist auf unbekannte gespeicherte Aktivitäten.");
    }
    return { ...state, activeRun };
  }
  return state;
}

export function validateLocalToursState(input: unknown): ToursState {
  const state = validateStateCollections(input);
  if (state.activeRun !== null) {
    throw new Error("Der gespeicherte Solid-Tours-Status darf keinen veröffentlichten Szenariolauf enthalten.");
  }
  return state;
}
